<?php $title='Monthly Summary'; require 'config/db.php'; require 'layout.php';
$rows=$pdo->query("SELECT month_key, SUM(action_type='Issued') issue_txn, SUM(CASE WHEN action_type='Issued' THEN quantity ELSE 0 END) issued, SUM(CASE WHEN action_type='Returned' THEN quantity ELSE 0 END) returned, SUM(CASE WHEN action_type='Received' THEN quantity ELSE 0 END) received FROM transactions GROUP BY month_key ORDER BY month_key DESC")->fetchAll(); ?>
<div class="card p-3"><table class="table"><thead><tr><th>Summary Period</th><th>Received</th><th>Issued</th><th>Returned</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['month_key']) ?></td><td><?= $r['received'] ?></td><td><?= $r['issued'] ?></td><td><?= $r['returned'] ?></td><td><a class="btn btn-sm btn-success" href="export.php?type=monthly&month=<?= e($r['month_key']) ?>">Download CSV</a></td></tr><?php endforeach; ?></tbody></table></div><?php require 'footer.php'; ?>
